const item = $input.first().json;
const messageId = item.id || item.threadId || ('email_' + Date.now());

const fromHeader = item.from?.value?.[0] || item.from || '';
let customer_name = '';
let customer_email = '';

if (typeof fromHeader === 'object' && fromHeader.address) {
  customer_name = fromHeader.name || '';
  customer_email = fromHeader.address || '';
} else {
  const match = String(fromHeader).match(/^(.*?)\s*<(.+?)>$/);
  if (match) {
    customer_name = match[1].replace(/^["']|["']$/g, '').trim();
    customer_email = match[2].trim();
  } else {
    customer_email = String(fromHeader).trim();
  }
}

const subject = item.subject || '';
let body = item.text || item.snippet || '';

// Strip quoted replies
body = body.replace(/^>.*$/gm, '');
// Strip "On ... wrote:"
body = body.replace(/On\s+[\s\S]+?wrote:[\s\S]*/gi, '');
// Strip signatures
body = body.replace(/--\s*[\r\n][\s\S]*/g, '');

body = body.trim();

let fullComment = subject ? `${subject} — ${body}` : body;
fullComment = fullComment.trim().slice(0, 2000);

if (fullComment.length < 3) {
  fullComment = (subject || 'Customer email feedback').slice(0, 2000);
}

return [{
  json: {
    source: 'email',
    source_ref: String(messageId),
    customer_name,
    customer_email,
    rating: null,
    comment: fullComment
  }
}];
